#include <bits/stdc++.h>
using namespace std;

static const int MOD=998244353;
inline int f_pref(int x,int c,int i,int n){
    return min(c,i)+max(0,i-n+x-c);
}
inline int f_suff(int x,int c,int i,int n){
    return max(0,c-i+1)+min(x-c,n-i+1);
}

void solve(){
    int n;
    if(!(cin>>n)) return;
    vector<int>a(n+1);
    vector<vector<int>>pos_of_val(n+1);
    for(int i=1;i<=n;i++){
        cin>>a[i];
        pos_of_val[a[i]].push_back(i);
    }
    
    vector<int>dp={1};
    
    for(int x=1;x<n;x++){
        vector<int>next_dp(x+2,0);
        for(int c_prev=0;c_prev<=x-1;c_prev++){
            if(dp[c_prev]==0) continue;
            
            for(int c_curr:{c_prev,c_prev+1}){
                bool valid=true;
                for(int i:pos_of_val[x]){
                    int T_pref=(i+1)/2;
                    int T_suff=(n-i+2)/2;
                    
                    bool cond_pref=(f_pref(x,c_curr,i,n)>=T_pref)&&(f_pref(x-1,c_prev,i,n)<T_pref);
                    bool cond_suff=(f_suff(x,c_curr,i,n)>=T_suff)&&(f_suff(x-1,c_prev,i,n)<T_suff);
                    
                    if(!cond_pref&&!cond_suff){
                        valid=false;
                        break;
                    }
                }
                if(valid){
                    next_dp[c_curr]=(next_dp[c_curr]+dp[c_prev])%MOD;
                }
            }
        }
        dp=move(next_dp);
    }
    for(int c=0;c<(int)dp.size();c++){
        if(dp[c]==0)continue;
        bool valid=true;
        for(int i:pos_of_val[n]){
            int T_pref=(i+1)/2;
            int T_suff=(n-i+2)/2;
            
            bool cond_pref=(f_pref(n-1,c,i,n)<T_pref);
            bool cond_suff=(f_suff(n-1,c,i,n)<T_suff);
             
            if(!cond_pref && !cond_suff){
                valid=false;
                break;
            }
        }
        if(!valid){
            dp[c]=0;
        }
    }
    long long ans=0;
    for(int count:dp){
        ans=(ans+count)%MOD;
    }
    cout<<ans<<"\n";
}

int main() {
	// your code goes here
	ios_base::sync_with_stdio(false);
	cin.tie(nullptr);
	int t;
	if(cin>>t){
	    while(t--){
	        solve();
	    }
	}
	return 0;
}
